    OPERATION_STATUS VARCHAR2(20 CHAR) NOT NULL DEFAULT 'REQUESTED',
    DELIVERY_STATUS VARCHAR2(20 CHAR) NOT NULL DEFAULT 'PENDING',
    ATTEMPT_COUNT NUMBER(10) NOT NULL DEFAULT 0,
