CREATE TABLE bat_center_cut_item (
    center_cut_item_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    center_cut_job_id VARCHAR2(100 CHAR) NOT NULL,
