COMMENT ON COLUMN bza_approval_delegation.valid_to IS '위임 종료시각';
COMMENT ON COLUMN bza_approval_delegation.reason IS '위임 사유';
COMMENT ON COLUMN bza_approval_delegation.use_yn IS '사용 여부';
