COMMENT ON COLUMN bza_approval_policy.policy_name IS '정책명';
COMMENT ON COLUMN bza_approval_policy.business_domain IS '적용 업무 영역';
COMMENT ON COLUMN bza_approval_policy.approval_type IS '적용 결재 유형';
COMMENT ON COLUMN bza_approval_policy.effective_from IS '시행 시작시각';
COMMENT ON COLUMN bza_approval_policy.effective_to IS '시행 종료시각';
COMMENT ON COLUMN bza_approval_policy.enabled_yn IS '활성 여부';
COMMENT ON COLUMN bza_approval_policy.self_approval_allowed_yn IS '자기승인 허용 여부';
