COMMENT ON COLUMN bza_approval_policy_step.step_no IS '결재 단계';
COMMENT ON COLUMN bza_approval_policy_step.step_type IS 'APPROVAL/AGREEMENT/REVIEW';
COMMENT ON COLUMN bza_approval_policy_step.target_type IS 'EMPLOYEE/ROLE/ORGANIZATION/ORG_MANAGER/POSITION';
COMMENT ON COLUMN bza_approval_policy_step.target_code IS '대상 코드';
COMMENT ON COLUMN bza_approval_policy_step.decision_rule IS 'ALL/ANY/N_OF_M';
COMMENT ON COLUMN bza_approval_policy_step.required_count IS 'N_OF_M 최소 결정 수';
COMMENT ON COLUMN bza_approval_policy_step.required_yn IS '필수 대상 여부';
COMMENT ON COLUMN bza_approval_policy_step.sort_order IS '동일 단계 표시 순서';
COMMENT ON COLUMN bza_approval_policy_step.created_by IS '등록자';
COMMENT ON COLUMN bza_approval_policy_step.created_at IS '등록일시';
COMMENT ON COLUMN bza_approval_policy_step.updated_by IS '수정자';
COMMENT ON COLUMN bza_approval_policy_step.updated_at IS '수정일시';
CREATE OR REPLACE TRIGGER trg_bza_approval_policy_step_touch
BEFORE UPDATE ON bza_approval_policy_step
FOR EACH ROW
BEGIN
    :NEW.updated_at := CURRENT_TIMESTAMP;
END;
/

CREATE TABLE bza_attachment (
    attachment_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    attachment_group_id VARCHAR2(80 CHAR) NOT NULL,
    original_file_name VARCHAR2(255 CHAR) NOT NULL,
    stored_file_name VARCHAR2(255 CHAR) NOT NULL,
    storage_key VARCHAR2(500 CHAR) NOT NULL,
    content_type VARCHAR2(120 CHAR) NOT NULL,
    file_size NUMBER(19) NOT NULL,
    checksum_sha256 CHAR(64 CHAR) NOT NULL,
    scan_status VARCHAR2(40 CHAR) NOT NULL DEFAULT 'PENDING',
    data_classification VARCHAR2(30 CHAR) NOT NULL DEFAULT 'INTERNAL',
    retention_until TIMESTAMP(3),
    quarantine_yn CHAR(1 CHAR) NOT NULL DEFAULT 'N',
    use_yn CHAR(1 CHAR) NOT NULL DEFAULT 'Y',
    created_by VARCHAR2(100 CHAR) NOT NULL DEFAULT 'SYSTEM',
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by VARCHAR2(100 CHAR) NOT NULL DEFAULT 'SYSTEM',
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (attachment_id),
    CONSTRAINT uk_bza_attachment_storage_key UNIQUE (storage_key),
    CONSTRAINT ck_bza_attachment_scan CHECK (scan_status IN ('PENDING','CLEAN','INFECTED','FAILED','QUARANTINED')),
    CONSTRAINT ck_bza_attachment_classification CHECK (data_classification IN ('PUBLIC','INTERNAL','CONFIDENTIAL','RESTRICTED')),
    CONSTRAINT ck_bza_attachment_quarantine CHECK (quarantine_yn IN ('Y','N'))
);
CREATE INDEX ix_bza_attachment_group ON bza_attachment (attachment_group_id, use_yn, created_at);
